    ]);
    assert.equal(whole.status, 404);
    assert.equal(whole.body.code, 'NOT_FOUND');
    const listed = await request(server.url, 'GET', '/documents');
    assert.deepEqual(listed.body.map((d) => d.id), ['a']);
  } finally {
    await server.stop();
  }
});

