    assert.equal(bad.body.code, 'INVALID_JSON');

    const doc = await request(server.url, 'GET', '/documents/a');
    assert.deepEqual(doc.body, { id: 'a', title: 'Alpha', body: 'original', tags: ['one'] });
    assert.equal(doc.etag, et);
